/* classic: one deque per worker; owner LIFO, thieves FIFO */
static void *worker(void *arg) {
    for (;;) {
        Task *t = deque_pop(pool->local[tid]);          /* newest first */
        if (!t) t = deque_steal(pool, other_worker());  /* oldest first */
        if (!t) break;                                  /* pool drained */
        run_task(t);     /* split() forks; join() helps until done */
    }
}

