#pragma omp parallel                      /* worker team (fork-join) */
#pragma omp single nowait
{
    #pragma omp taskgroup                 /* join: child tasks + descendants */
    {
        #pragma omp task shared(a) in_reduction(+:total)
        { total += sum(a, lo, mid); }     /* fork */
        total += sum(a, mid, hi);         /* this task computes the other half */
    }
}
